mapper.select:
SELECT SUM(CASE WHEN duration IS NULL THEN 0 ELSE duration END) AS duration, SUM(CASE WHEN distance IS NULL THEN 0 ELSE distance END) AS distance, COUNT(id) AS times, SUM(checkins) AS checkins FROM ( SELECT a.id, a.duration, a.distance, COUNT(b.id) AS checkins FROM ur_sport_record a LEFT JOIN ur_sport_checkin b ON a.id = b.group_id AND b.db_status = 1 WHERE a.db_status = 1 AND a.user_id = #{ params.userId }
and a.start_time >= #{params.startDate}
and a.start_time <= #{params.endDate}
GROUP BY a.id, a.duration, a.distance)
